<header class="page-header"><div><p class="eyebrow">Prospect</p><h1><?= $prospect?'Edit prospect':'New prospect' ?></h1><p>Add the company or person you need without leaving this form.</p></div></header><?php if($errors!==[]):?><div class="validation-summary" role="alert" tabindex="-1" data-validation-summary><h2>Please review</h2><ul><?php foreach($errors as $k=>$m):?><li><?= $escape($m) ?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" action="<?= $escape($actionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><?php if($prospect):?><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><?php endif;?><div class="field-grid"><div class="form-field"><label for="prospect-company">Company</label><div class="select-with-action"><select id="prospect-company" name="company_id"><option value="">No company</option><?php foreach($companies as $c):?><option value="<?= $escape($c['id']) ?>"<?= (string)($values['company_id']??'')===(string)$c['id']?' selected':'' ?>><?= $escape($c['name']) ?></option><?php endforeach;?></select><button type="button" class="button button--secondary" data-dialog-open="quick-company">Add company</button></div></div><div class="form-field"><label for="prospect-contact">Primary contact</label><div class="select-with-action"><select id="prospect-contact" name="primary_contact_id"><option value="">No contact</option><?php foreach($contacts as $c):?><option value="<?= $escape($c['id']) ?>"<?= (string)($values['primary_contact_id']??'')===(string)$c['id']?' selected':'' ?>><?= $escape(trim(($c['first_name']??'').' '.($c['last_name']??''))) ?><?= $c['company_name']?' — '.$escape($c['company_name']):' — Independent' ?></option><?php endforeach;?></select><button type="button" class="button button--secondary" data-dialog-open="quick-contact">Add contact</button></div></div><fieldset class="segment-choices"><legend>Segment</legend><?php foreach($segments as $k=>$label):?><label class="checkbox-field"><input type="radio" name="segment" value="<?= $escape($k) ?>"<?= ($values['segment']??'')===$k?' checked':'' ?> required> <?= $escape($label) ?></label><?php endforeach;?></fieldset><label>Source<input name="source" value="<?= $escape($values['source']??'') ?>"></label></div><label>Why them?<textarea name="why_them" rows="4"><?= $escape($values['why_them']??'') ?></textarea></label><label>Business problem<textarea name="business_problem" rows="4"><?= $escape($values['business_problem']??'') ?></textarea></label><label>Qualification notes<textarea name="qualification_notes" rows="4"><?= $escape($values['qualification_notes']??'') ?></textarea></label><fieldset><legend>Qualification understanding</legend><?php foreach(['problem_understood'=>'Problem','timing_understood'=>'Timing','buyer_understood'=>'Buyer','budget_plausible'=>'Plausible budget'] as $k=>$label):?><label class="checkbox-field"><input type="checkbox" name="<?= $escape($k) ?>" value="1"<?= !empty($values[$k])?' checked':'' ?>> <?= $escape($label) ?></label><?php endforeach;?></fieldset><div class="form-actions"><button>Save prospect</button><a href="<?= $escape($cancelUrl) ?>">Cancel</a></div></form><dialog id="quick-company" aria-labelledby="quick-company-heading"><form method="dialog"><div class="dialog-header"><h2 id="quick-company-heading">Add company</h2><button type="submit" aria-label="Close">×</button></div></form><form method="post" action="<?= $escape($quickCompanyUrl) ?>" data-quick-create data-target-select="prospect-company"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><p class="form-error" data-quick-error hidden></p><label>Company name<input name="name" required maxlength="160" autofocus></label><label>Website <span class="muted">(optional)</span><input name="website" type="url"></label><div class="form-actions"><button type="submit">Add company</button><button type="button" data-dialog-close>Cancel</button></div></form></dialog><dialog id="quick-contact" aria-labelledby="quick-contact-heading"><form method="dialog"><div class="dialog-header"><h2 id="quick-contact-heading">Add contact</h2><button type="submit" aria-label="Close">×</button></div></form><form method="post" action="<?= $escape($quickContactUrl) ?>" data-quick-create data-target-select="prospect-contact"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><p class="form-error" data-quick-error hidden></p><div class="field-grid"><label>First name<input name="first_name" maxlength="100"></label><label>Last name<input name="last_name" maxlength="100"></label></div><label>Company <span class="muted">(optional)</span><select name="company_id" data-copy-company><option value="">Independent contact</option><?php foreach($companies as $c):?><option value="<?= $escape($c['id']) ?>"><?= $escape($c['name']) ?></option><?php endforeach;?></select></label><label>Email <span class="muted">(optional)</span><input name="email" type="email"></label><div class="form-actions"><button type="submit">Add contact</button><button type="button" data-dialog-close>Cancel</button></div></form></dialog>
